const crypto = require('crypto');
const { URL } = require('url');

class TokenService {
  constructor(config) {
    this.secrets = new Map();
    this.revokedTokens = new Set();
    this.allowedAlgorithms = new Set(['HS256', 'HS384', 'HS512']);
    this.issuer = config.issuer || 'auth-service';
    this.maxClockSkew = config.maxClockSkew || 30;
    this.audiences = new Set(config.audiences || []);

    // Initialize signing keys per algorithm
    for (const [alg, secret] of Object.entries(config.secrets || {})) {
      if (this.allowedAlgorithms.has(alg)) {
        this.secrets.set(alg, Buffer.from(secret, 'base64'));
      }
    }
  }

  _base64UrlEncode(data) {
    return Buffer.from(data)
      .toString('base64')
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=+$/, '');
  }

  _base64UrlDecode(str) {
    str = str.replace(/-/g, '+').replace(/_/g, '/');
    const pad = str.length % 4;
    if (pad === 2) str += '==';
    else if (pad === 3) str += '=';
    return Buffer.from(str, 'base64');
  }

  _getHashAlgorithm(alg) {
    const mapping = {
      'HS256': 'sha256',
      'HS384': 'sha384',
      'HS512': 'sha512'
    };
    return mapping[alg] || null;
  }

  _computeSignature(algorithm, signingInput) {
    const hashAlg = this._getHashAlgorithm(algorithm);
    if (!hashAlg) return null;
    const secret = this.secrets.get(algorithm);
    if (!secret) return null;
    return crypto.createHmac(hashAlg, secret)
      .update(signingInput)
      .digest();
  }

  createToken(payload, algorithm = 'HS256') {
    if (!this.allowedAlgorithms.has(algorithm)) {
      throw new Error(`Unsupported algorithm: ${algorithm}`);
    }

    const header = { alg: algorithm, typ: 'JWT' };
    const now = Math.floor(Date.now() / 1000);

    const fullPayload = {
      ...payload,
      iss: this.issuer,
      iat: now,
      exp: payload.exp || now + 3600,
      jti: crypto.randomUUID()
    };

    const headerEncoded = this._base64UrlEncode(JSON.stringify(header));
    const payloadEncoded = this._base64UrlEncode(JSON.stringify(fullPayload));
    const signingInput = `${headerEncoded}.${payloadEncoded}`;

    const signature = this._computeSignature(algorithm, signingInput);
    if (!signature) throw new Error('Failed to compute signature');

    const signatureEncoded = this._base64UrlEncode(signature);
    return `${signingInput}.${signatureEncoded}`;
  }

  _validateStructure(token) {
    if (typeof token !== 'string') return null;
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    try {
      const header = JSON.parse(this._base64UrlDecode(parts[0]).toString('utf8'));
      const payload = JSON.parse(this._base64UrlDecode(parts[1]).toString('utf8'));
      const signature = this._base64UrlDecode(parts[2]);
      return { header, payload, signature, signingInput: `${parts[0]}.${parts[1]}` };
    } catch (e) {
      return null;
    }
  }

  _validateHeader(header) {
    if (!header || typeof header !== 'object') return false;
    if (header.typ && header.typ !== 'JWT') return false;
    // Verify algorithm is in our allowed set
    if (!header.alg) return false;
    return true;
  }

  _validateClaims(payload) {
    const now = Math.floor(Date.now() / 1000);

    // Check expiration
    if (payload.exp !== undefined) {
      if (typeof payload.exp !== 'number') return { valid: false, reason: 'invalid exp type' };
      if (now > payload.exp + this.maxClockSkew) {
        return { valid: false, reason: 'token expired' };
      }
    }

    // Check not-before
    if (payload.nbf !== undefined) {
      if (typeof payload.nbf !== 'number') return { valid: false, reason: 'invalid nbf type' };
      if (now < payload.nbf - this.maxClockSkew) {
        return { valid: false, reason: 'token not yet valid' };
      }
    }

    // Check issuer
    if (payload.iss !== this.issuer) {
      return { valid: false, reason: 'invalid issuer' };
    }

    // Check audience if specified
    if (payload.aud) {
      const audiences = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
      const hasValidAudience = audiences.some(a => this.audiences.has(a));
      if (!hasValidAudience) {
        return { valid: false, reason: 'invalid audience' };
      }
    }

    return { valid: true };
  }

  _verifySignature(header, signingInput, providedSignature) {
    const algorithm = header.alg;

    // Check if algorithm is allowed
    if (!this.allowedAlgorithms.has(algorithm)) {
      // For unrecognized algorithms, check if it's a known-unsafe one
      const unsafeAlgorithms = ['none', 'None', 'NONE'];
      if (unsafeAlgorithms.includes(algorithm)) {
        return false;
      }
      return false;
    }

    const expectedSignature = this._computeSignature(algorithm, signingInput);
    if (!expectedSignature) return false;

    // Constant-time comparison
    if (expectedSignature.length !== providedSignature.length) return false;
    return crypto.timingSafeEqual(expectedSignature, providedSignature);
  }

  verifyToken(token, options = {}) {
    // Step 1: Structural validation
    const parsed = this._validateStructure(token);
    if (!parsed) {
      return { valid: false, reason: 'malformed token' };
    }

    // Step 2: Header validation
    if (!this._validateHeader(parsed.header)) {
      return { valid: false, reason: 'invalid header' };
    }

    // Step 3: Check revocation
    if (parsed.payload.jti && this.revokedTokens.has(parsed.payload.jti)) {
      return { valid: false, reason: 'token revoked' };
    }

    // Step 4: Claims validation
    const claimsResult = this._validateClaims(parsed.payload);
    if (!claimsResult.valid) {
      return claimsResult;
    }

    // Step 5: Signature verification
    if (!this._verifySignature(parsed.header, parsed.signingInput, parsed.signature)) {
      return { valid: false, reason: 'invalid signature' };
    }

    return { valid: true, payload: parsed.payload };
  }

  revokeToken(jti) {
    this.revokedTokens.add(jti);
  }
}

class AuthMiddleware {
  constructor(tokenService) {
    this.tokenService = tokenService;
  }

  authenticate(req, res, next) {
    const authHeader = req.headers && req.headers.authorization;
    if (!authHeader) {
      return res.status(401).json({ error: 'No authorization header' });
    }

    const match = authHeader.match(/^Bearer\s+(.+)$/);
    if (!match) {
      return res.status(401).json({ error: 'Invalid authorization format' });
    }

    const token = match[1];
    const result = this.tokenService.verifyToken(token);

    if (result.valid) {
      req.user = result.payload;
      return next();
    }

    return res.status(401).json({ error: result.reason });
  }
}

module.exports = { TokenService, AuthMiddleware };
